def test_request_state_object() -> None:
    state = UserDict({"old": "foo"})
    scope = {"state": state}

    s = State(scope["state"])

    s.new = "value"
    assert s.new == "value"
    assert state["new"] == "value"

    s["mapped"] = "value"
    assert s["mapped"] == "value"
    assert state["mapped"] == "value"
    assert list(s) == ["old", "new", "mapped"]
    assert len(s) == 3

    del s.new
    del s["mapped"]

    with pytest.raises(AttributeError):
        s.new

    with pytest.raises(KeyError):
        s["mapped"]


def test_request_state(test_client_factory: TestClientFactory) -> None:
    async def app(scope: Scope, receive: Receive, send: Send) -> None:
        request = Request(scope, receive)
        request.state.example = 123
        response = JSONResponse({"state.example": request.state.example})
        await response(scope, receive, send)

    client = test_client_factory(app)
    response = client.get("/123?a=abc")
    assert response.json() == {"state.example": 123}


def test_request_state_preserves_mutable_mapping() -> None:
    shared: list[str] = []
    state: UserDict[str, Any] = UserDict({"shared": shared})
    scope: Scope = {"type": "http", "state": state}
    request = Request(scope)

    request.state["new"] = "value"

    assert state["new"] == "value"
    assert request.state["shared"] is shared


